import{_ as n,c as t,o as a,ag as s}from"./chunks/framework.Ci10AEOF.js";const m=JSON.parse('{"title":"Migrating from Mirth Connect on macOS","description":"Not yet written. What a macOS version of the migration procedure needs to cover","frontmatter":{"title":"Migrating from Mirth Connect on macOS","description":"Not yet written. What a macOS version of the migration procedure needs to cover"},"headers":[],"relativePath":"engine/migrating_macos.md","filePath":"engine/migrating_macos.md","lastUpdated":1793057853000}'),i={name:"engine/migrating_macos.md"};function o(p,e,r,c,l,h){return a(),t("div",null,e[0]||(e[0]=[s(`<h1 id="migrating-from-mirth-connect-on-macos" tabindex="-1">Migrating from Mirth Connect on macOS <a class="header-anchor" href="#migrating-from-mirth-connect-on-macos" aria-label="Permalink to &quot;Migrating from Mirth Connect on macOS&quot;">​</a></h1><p><strong>This page is not written yet.</strong> Contributions welcome, see <a href="./contributing.html">Contributing</a>.</p><p>Read <a href="./migrating_from_mirth_connect.html">Migrating from Mirth Connect</a> for the part that does not change with the platform: what OIE keeps from Mirth, what migrates, how extensions are checked, what the keystore holds, and the backups to take first.</p><p>Throughout this page Mirth Connect is installed at <code>/Applications/Mirth Connect</code> and OIE at <code>/Applications/OpenIntegrationEngine</code>. The OIE path is the documented default, see <a href="./installation.html">Installation</a>. Substitute your own.</p><p><a href="./migrating_linux.html">Migrating on Linux</a> is the template. The eleven steps are the same. These steps need macOS equivalents, against the launchd daemon <code>com.oie.oieservice</code> defined in <code>/Library/LaunchDaemons/com.oie.oieservice.plist</code>:</p><ul><li><strong>Step 4</strong>, the account the daemon runs as, set in the plist rather than a systemd drop-in.</li><li><strong>Steps 5, 7, 10 and 11</strong>, <code>launchctl</code> in place of <code>systemctl</code> for starting, stopping and unloading the daemon, and confirming the process is gone.</li><li><strong>Step 8</strong>, copying the application data, and the <code>chown</code> that has to follow it.</li></ul><p>See <a href="./server_process_management.html">Server Process Management</a> for how the daemon is managed on macOS.</p><h2 id="what-this-touches" tabindex="-1">What this touches <a class="header-anchor" href="#what-this-touches" aria-label="Permalink to &quot;What this touches&quot;">​</a></h2><p>The tree below lists everything the procedure edits or copies, and the step that does it. See <a href="./installation.html">Installation</a> for the full directory listing.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/Applications/OpenIntegrationEngine/</span></span>
<span class="line"><span>├── appdata/                        # replaced wholesale from Mirth (step 8)</span></span>
<span class="line"><span>│   ├── keystore.jks</span></span>
<span class="line"><span>│   ├── server.id</span></span>
<span class="line"><span>│   ├── configuration.properties</span></span>
<span class="line"><span>│   ├── extension.properties</span></span>
<span class="line"><span>│   └── mirthdb/                    # kept on Derby, deleted on an external database (step 8)</span></span>
<span class="line"><span>├── conf/</span></span>
<span class="line"><span>│   ├── mirth.properties            # edit (steps 2, 3, 6 and 9)</span></span>
<span class="line"><span>│   ├── dbdrivers.xml               # copy if you added driver entries (step 6)</span></span>
<span class="line"><span>│   ├── log4j2.properties           # merge custom appenders (step 6)</span></span>
<span class="line"><span>│   ├── mirth-cli-config.properties # copy if you customised it (step 6)</span></span>
<span class="line"><span>│   └── custom.vmoptions            # set JVM settings again, no Mirth equivalent (step 6)</span></span>
<span class="line"><span>├── custom-lib/                     # copy if you use it, not created by the installer (step 6)</span></span>
<span class="line"><span>├── extensions/                     # see Extension compatibility (step 6)</span></span>
<span class="line"><span>└── logs/</span></span>
<span class="line"><span>    └── mirth.log                   # watch (steps 5 and 10)</span></span></code></pre></div>`,10)]))}const g=n(i,[["render",o]]);export{m as __pageData,g as default};
